import os

def handler(event, context):
    part = event.get("part_number") if isinstance(event, dict) else None
    if part != os.environ["DEMO_PART_NUMBER"]:
        return {"found": False, "part_number": part, "data_kind": "synthetic_demo"}
    return {
        "found": True,
        "part_number": part,
        "warehouse": "DEMO-CN",
        "quantity": 12,
        "unit": "piece",
        "data_kind": "synthetic_demo"
    }
